/* HEXA BATTLEGROUNDS setup — PART 22 OF 32. Run parts in order. Safe to re-run. */ create or replace function _shift_arena(p_arena uuid, p_delta interval) returns void language plpgsql as $$ begin update arenas set shuttle_departed_at = shuttle_departed_at + p_delta, shuttle_arrive_at = shuttle_arrive_at + p_delta, roles_deadline = roles_deadline + p_delta, play_started_at = play_started_at + p_delta, zone_next_at = zone_next_at + p_delta, last_airdrop_at = last_airdrop_at + p_delta, phase_started_at = phase_started_at + p_delta, phase_next_at = phase_next_at + p_delta, red_at = red_at + p_delta, last_red_at = last_red_at + p_delta, overlay = case when overlay ? 'match' then jsonb_set(overlay, '{match,next_at}', coalesce(to_jsonb((overlay #>> '{match,next_at}')::timestamptz + p_delta), 'null'::jsonb)) else overlay end where id = p_arena; update mission_instances set deadline = deadline + p_delta, fallback_at = fallback_at + p_delta, started_at = started_at + p_delta where arena_id = p_arena and status = 'active'; update battles set deadline = deadline + p_delta, started_at = started_at + p_delta where arena_id = p_arena and status = 'active'; update sync_rounds set deadline = deadline + p_delta, started_at = started_at + p_delta where arena_id = p_arena and status = 'active'; update airdrops set expires_at = expires_at + p_delta, spawned_at = spawned_at + p_delta where arena_id = p_arena and status = 'open'; update alliances set expires_at = expires_at + p_delta, created_at = created_at + p_delta where arena_id = p_arena and status in ('proposed', 'active'); update story_events set expires_at = expires_at + p_delta where arena_id = p_arena and expires_at > now(); update teams set zone_hit_at = zone_hit_at + p_delta, travel_started_at = travel_started_at + p_delta, travel_arrive_at = travel_arrive_at + p_delta, recovery_deadline = recovery_deadline + p_delta, attack_cooldown_until = attack_cooldown_until + p_delta, protected_until = protected_until + p_delta, jammed_until = jammed_until + p_delta, scan_until = scan_until + p_delta where arena_id = p_arena; perform _zone_publish(p_arena); end $$; create or replace function _tick(p_arena uuid, p_force boolean default false) returns boolean language plpgsql as $$ declare a arenas; r record; tm teams; c float8[]; xy float8[]; v_tick int; v_bucket bigint; v_changed boolean := false; v_sched text[]; v_next int; v_at timestamptz; v_target int; begin if not pg_try_advisory_xact_lock(hashtext('tick' || p_arena::text)) then return false; end if; select * into a from arenas where id = p_arena; if a.id is null or a.paused then return false; end if; if not p_force and a.last_tick_at is not null and a.last_tick_at > now() - interval '800 milliseconds' then return false; end if; update arenas set last_tick_at = now() where id = p_arena; if a.phase = 'shuttle' and now() >= a.shuttle_arrive_at then update arenas set phase = 'roles', roles_deadline = now() + _secs(_cfg(a.event_id, 'roles_seconds')) where id = p_arena; update teams set location_id = 'gate_1', state = 'idle' where arena_id = p_arena and ready; perform _feed(p_arena, 'shuttle.arrived', '{}'::jsonb); v_changed := true; end if; select * into a from arenas where id = p_arena; if a.phase = 'roles' and now() >= a.roles_deadline then perform _finalize_roles(p_arena); update arenas set phase = 'play', play_started_at = now() where id = p_arena; perform _feed(p_arena, 'role.assignment.completed', '{}'::jsonb); perform _feed(p_arena, 'map.revealed', '{}'::jsonb); perform _set_match_phase(p_arena, 0); v_changed := true; end if; select * into a from arenas where id = p_arena; if a.phase not in ('play', 'finale') then if v_changed then perform _ping_arena(p_arena, 'phase'); end if; return v_changed; end if; for r in select id from teams where arena_id = p_arena and state = 'traveling' and travel_arrive_at <= now() loop perform _arrive(r.id); v_changed := true; end loop; for r in select id from battles where arena_id = p_arena and status = 'active' and deadline <= now() loop perform _resolve_battle(r.id, null); v_changed := true; end loop; for r in select id, kind, sync_round_id from mission_instances where arena_id = p_arena and status = 'active' and deadline <= now() and kind <> 'battle' loop perform _fail(r.id, 'expired'); v_changed := true; end loop; for r in select id from teams where arena_id = p_arena and state = 'recovery' and recovery_deadline <= now() loop perform _respawn(r.id, 'timeout'); v_changed := true; end loop; for r in select id from sync_rounds where arena_id = p_arena and status = 'active' and deadline <= now() loop update sync_rounds set status = 'closed' where id = r.id; update arenas set sync_round_id = null where id = p_arena and sync_round_id = r.id; perform _feed(p_arena, 'sync.closed', '{}'::jsonb); v_changed := true; end loop; select * into a from arenas where id = p_arena; if a.phase = 'play' and a.match_phase < 4 and a.phase_next_at is not null and now() >= a.phase_next_at then perform _set_match_phase(p_arena, a.match_phase + 1); v_changed := true; end if; select * into a from arenas where id = p_arena; if a.phase = 'play' and not a.zone_hold and a.zone_next_at is null and a.zone_stage < 5 then v_target := _phase_zone_target(a.match_phase); if a.zone_stage < v_target then update arenas set zone_next_at = now() + _secs(_cfg(a.event_id, 'zone_warning')) where id = p_arena; perform _feed(p_arena, 'zone.warning', jsonb_build_object('stage', a.zone_stage + 1)); v_changed := true; end if; end if; select * into a from arenas where id = p_arena; if a.phase = 'play' and _cfg(a.event_id, 'zone_auto') = 1 and a.zone_next_at is null and a.zone_stage < 5 and not a.zone_hold then v_sched := string_to_array(_cfg_text(a.event_id, 'zone_schedule'), ','); v_next := trim(v_sched[a.zone_stage + 1])::int; if v_next is not null then v_at := a.play_started_at + make_interval(mins => v_next); if now() >= v_at - _secs(_cfg(a.event_id, 'zone_warning')) then update arenas set zone_next_at = greatest(v_at, now() + interval '10 seconds') where id = p_arena; perform _feed(p_arena, 'zone.warning', jsonb_build_object('stage', a.zone_stage + 1)); v_changed := true; end if; end if; end if; select * into a from arenas where id = p_arena; if a.zone_next_at is not null and now() >= a.zone_next_at then perform _zone_advance(p_arena); v_changed := true; end if; select * into a from arenas where id = p_arena; if a.phase = 'play' then c := _zone_circle(a.event_id, a.zone_stage); v_tick := greatest(2, _cfg(a.event_id, 'zone_tick_seconds')); v_bucket := floor(extract(epoch from now()) / v_tick)::bigint; for tm in select * from teams where arena_id = p_arena and ready and state <> 'recovery' and (zone_hit_at is null or zone_hit_at <= now() - _secs(v_tick)) loop xy := _team_xy(tm); if not _in_circle(c, xy[1], xy[2]) then update teams set zone_hit_at = now() where id = tm.id; perform _damage(tm.id, _cfg(a.event_id, 'zone_tick_damage'), 'zone_damage', 'zt-' || v_bucket, 'Outside the safe zone'); perform _ping_team(tm.id, 'zone'); v_changed := true; end if; end loop; end if; select * into a from arenas where id = p_arena; if a.red_at is not null and now() >= a.red_at then perform _red_strike(p_arena); v_changed := true; elsif a.phase = 'play' and a.red_at is null and a.match_phase >= 2 and _cfg(a.event_id, 'red_interval') > 0 and coalesce(a.last_red_at, a.phase_started_at, a.play_started_at) < now() - make_interval(mins => _cfg(a.event_id, 'red_interval')) then perform _red_spawn(p_arena); v_changed := true; end if; if a.phase = 'play' and _cfg(a.event_id, 'airdrop_interval') > 0 and coalesce(a.last_airdrop_at, a.play_started_at) < now() - make_interval(mins => _cfg(a.event_id, 'airdrop_interval')) then perform _spawn_airdrop(p_arena, null, (array['common', 'common', 'rare', 'mystery', 'intel', 'cursed', 'legendary'])[1 + floor(random() * 7)::int]); v_changed := true; end if; update airdrops set status = 'expired' where arena_id = p_arena and status = 'open' and expires_at <= now(); if found then v_changed := true; end if; update mission_instances mi set status = 'cancelled' from airdrops ad where mi.airdrop_id = ad.id and ad.status = 'expired' and mi.status = 'active'; update alliances set status = 'expired' where arena_id = p_arena and status = 'proposed' and created_at < now() - interval '2 minutes'; update alliances set status = 'ended' where arena_id = p_arena and status = 'active' and expires_at <= now(); if v_changed then perform _zone_publish(p_arena); perform _ping_arena(p_arena, 'tick'); end if; return v_changed; end $$; create or replace function _set_match_phase(p_arena uuid, p_phase int) returns void language plpgsql as $$ declare a arenas; e events; v_next timestamptz; v_sched text[]; v_min int; begin select * into a from arenas where id = p_arena for update; select * into e from events where id = a.event_id; p_phase := greatest(0, least(5, p_phase)); if p_phase < 4 and _cfg(a.event_id, 'auto_pacing') = 1 and a.play_started_at is not null then v_sched := string_to_array(_cfg_text(a.event_id, 'phase_schedule'), ','); begin v_min := nullif(trim(v_sched[p_phase + 1]), '')::int; exception when others then v_min := null; end; if v_min is not null then v_next := greatest(now() + interval '5 seconds', a.play_started_at + make_interval(mins => v_min)); end if; end if; update arenas set match_phase = p_phase, phase_started_at = now(), phase_next_at = v_next, zone_hold = false, overlay = overlay || jsonb_build_object('match', jsonb_build_object( 'phase', p_phase, 'started_at', now(), 'next_at', v_next, 'duel_phase', _cfg(a.event_id, 'duel_phase'), 'zone_target', _phase_zone_target(p_phase))) where id = p_arena; if a.match_phase is distinct from p_phase or a.phase_started_at is null then perform _feed(p_arena, 'phase.started', jsonb_build_object('phase', p_phase)); end if; perform _zone_publish(p_arena); perform _ping_arena(p_arena, 'phase'); end $$; create or replace function captain_move(p_token text, p_location text) returns jsonb language plpgsql security definer set search_path = public as $$ declare p players; t teams; a arenas; l locations; v_secs numeric; cur float8[]; d float8; begin p := _auth_captain(p_token); select * into t from teams where id = p.team_id for update; select * into a from arenas where id = t.arena_id; if a.phase <> 'play' then raise exception 'NO_MOVES_NOW'; end if; if t.state = 'recovery' then raise exception 'BUSY'; end if; if exists (select 1 from mission_instances where team_id = t.id and status = 'active' and kind = 'battle') then raise exception 'IN_BATTLE'; end if; select * into l from locations where id = p_location; if l.id is null or l.kind = 'start' or not l.enabled then raise exception 'BAD_LOCATION'; end if; if l.id = t.location_id and t.state = 'idle' then raise exception 'ALREADY_HERE'; end if; cur := _team_xy(t); d := sqrt((l.x - cur[1]) ^ 2 + (l.y - cur[2]) ^ 2); if not t.dropped then v_secs := _cfg(t.event_id, 'drop_seconds'); else v_secs := greatest(1, round((d / (_cfg(t.event_id, 'move_speed') / 1000.0))::numeric, 1)); end if; update mission_instances set status = 'cancelled' where team_id = t.id and status = 'active' and kind in ('mission', 'relay', 'airdrop') and sync_round_id is null; update teams set state = 'traveling', travel_from = location_id, travel_to = l.id, travel_started_at = now(), travel_arrive_at = now() + _secs(v_secs), travel_fx = cur[1], travel_fy = cur[2], pos_x = cur[1], pos_y = cur[2], pos_at = now() where id = t.id; if t.jammed_until is null or t.jammed_until < now() then perform _feed(t.arena_id, 'squad.movement.started', jsonb_build_object('team', t.number, 'from', t.location_id, 'to', l.id)); end if; perform _ping_team(t.id, 'move'); perform _ping_arena(t.arena_id, 'move'); return jsonb_build_object('arrive_at', now() + _secs(v_secs), 'seconds', v_secs); end $$; create or replace function captain_explore(p_token text) returns jsonb language plpgsql security definer set search_path = public as $$ declare p players; t teams; v_id uuid; begin p := _auth_captain(p_token); select * into t from teams where id = p.team_id for update; if (select phase from arenas where id = t.arena_id) <> 'play' then raise exception 'NO_MOVES_NOW'; end if; if t.state <> 'idle' then raise exception 'BUSY'; end if; if t.location_id is null then raise exception 'NOT_AT_LOCATION'; end if; if exists (select 1 from mission_instances where team_id = t.id and status = 'active' and kind <> 'battle') then raise exception 'MISSION_ACTIVE'; end if; if t.visit_missions >= _cfg(t.event_id, 'visit_missions') then raise exception 'AREA_EXHAUSTED'; end if; v_id := _start_location_mission(t.id); if v_id is null then raise exception 'NO_MISSIONS'; end if; return jsonb_build_object('instance', v_id); end $$; create or replace function captain_buy(p_token text, p_item text) returns jsonb language plpgsql security definer set search_path = public as $$ declare p players; t teams; l locations; it items; begin p := _auth_captain(p_token); select * into t from teams where id = p.team_id for update; select * into l from locations where id = t.location_id; if t.state <> 'idle' or l.id is null or not (l.tags && array['market', 'social']) then raise exception 'NO_MARKET_HERE'; end if; select * into it from items where id = p_item; if it.id is null or it.price <= 0 then raise exception 'BAD_ITEM'; end if; if 'social' = any(l.tags) and not ('market' = any(l.tags)) and it.kind not in ('intel', 'stealth', 'airdrop') then raise exception 'NOT_SOLD_HERE'; end if; if t.coins < it.price then raise exception 'NOT_ENOUGH_COINS'; end if; perform _apply(t.id, 'purchase', 0, -it.price, 0, 0, null, 'Bought ' || it.name); perform _add_item(t.id, p_item, 1); perform _ping_team(t.id, 'item'); return jsonb_build_object('bought', p_item); end $$; create or replace function captain_use_item(p_token text, p_item text) returns jsonb language plpgsql security definer set search_path = public as $$ declare p players; t teams; a arenas; it items; v_qty int; v_dest text; begin p := _auth_captain(p_token); select * into t from teams where id = p.team_id for update; select * into a from arenas where id = t.arena_id; select * into it from items where id = p_item; if it.id is null then raise exception 'BAD_ITEM'; end if; if it.kind = 'weapon' then raise exception 'USE_ATTACK'; end if; select qty into v_qty from inventory where team_id = t.id and item_id = p_item; if coalesce(v_qty, 0) < 1 then raise exception 'NO_ITEM'; end if; if t.state = 'recovery' and p_item <> 'medkit' then raise exception 'IN_RECOVERY'; end if; case p_item when 'medkit' then if t.state = 'recovery' then raise exception 'IN_RECOVERY'; end if; if t.hp >= _cfg(t.event_id, 'hp_max') then raise exception 'HP_FULL'; end if; perform _apply(t.id, 'medkit', 0, 0, (it.params ->> 'heal')::int, 0, null, 'Used a med kit'); when 'shield' then update teams set shield = least(_cfg(t.event_id, 'shield_max'), shield + (it.params ->> 'shield')::int) where id = t.id; when 'scanner' then update teams set scan_until = now() + _secs((it.params ->> 'seconds')::int) where id = t.id; when 'jammer' then update teams set jammed_until = now() + _secs((it.params ->> 'seconds')::int) where id = t.id; when 'beacon' then if t.beacon then raise exception 'ALREADY_ACTIVE'; end if; update teams set beacon = true where id = t.id; when 'extract' then if a.phase <> 'play' then raise exception 'NO_MOVES_NOW'; end if; if exists (select 1 from mission_instances where team_id = t.id and status = 'active' and kind = 'battle') then raise exception 'IN_BATTLE'; end if; v_dest := _nearest_safe_xy(a.event_id, least(5, a.zone_stage + 1), (_team_xy(t))[1], (_team_xy(t))[2]); update mission_instances set status = 'cancelled' where team_id = t.id and status = 'active' and kind in ('mission', 'relay', 'airdrop'); update teams set state = 'idle', location_id = v_dest, pos_x = (_loc_xy(v_dest))[1], pos_y = (_loc_xy(v_dest))[2], pos_at = now(), travel_to = null, travel_from = null, travel_arrive_at = null, travel_fx = null, travel_fy = null, dropped = true, visit_missions = 0 where id = t.id; else raise exception 'BAD_ITEM'; end case; perform _add_item(t.id, p_item, -1); insert into ledger(arena_id, team_id, kind, ref, reason, actor) values (t.arena_id, t.id, 'item_used', null, p_item, 'captain'); perform _ping_team(t.id, 'item'); return jsonb_build_object('used', p_item, 'location', v_dest); end $$;
